#!/usr/bin/env python3
"""Margin glosses for episodes 1–8: one per panel, in three voices.

Each row: kids (en, ru), parents (en, ru),
          orthodox (source id, where en, where ru, text en, text ru),
          protestant (source id, where en, where ru, text en, text ru)
All commentary is paraphrase, flagged for checking against the source.
Run:  python3 tools/authoring/glosses_s1.py   (after season1.py)
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def G(k, p, o, r):
    return {"kids": {"en": k[0], "ru": k[1]}, "parents": {"en": p[0], "ru": p[1]},
            "adults": {"orthodox": {"source": o[0], "where": {"en": o[1], "ru": o[2]}, "kind": "paraphrase", "verify": True, "text": {"en": o[3], "ru": o[4]}},
                       "protestant": {"source": r[0], "where": {"en": r[1], "ru": r[2]}, "kind": "paraphrase", "verify": True, "text": {"en": r[3], "ru": r[4]}}}}


