RY = lambda v: ("ryle", f"Expository Thoughts on Mark {v}", f"Размышления на Мк {v}")
HE = lambda v: ("henry", f"Commentary on Mark {v}", f"Комментарий на Мк {v}")
BA = lambda v: ("barnes", f"Notes on Mark {v}", f"Заметки на Мк {v}")
LO = lambda v: ("lopukhin", f"Explanatory Bible, on Mk {v}", f"Толковая Библия, на Мк {v}")
TF = ("theophan", "Thoughts for Each Day of the Year", "Мысли на каждый день года")

